import java.util.*;
class Test {public static void main(String[] args){Solution s=new Solution();String[][] c={{"aa","a","false"},{"aa","*","true"},{"cb","?a","false"},{"adceb","*a*b","true"},{"acdcb","a*c?b","false"},{"","","true"},{"","***","true"},{"a","","false"}};for(String[] x:c)if(s.isMatch(x[0],x[1])!=Boolean.parseBoolean(x[2]))throw new AssertionError();String[] tokens={"a","b","?","*"};for(String a:new String[]{"","a","b","aa","ab","baa"})for(String x:tokens)for(String y:tokens)for(String z:tokens){String p=x+y+z,r=p.replace("?",".").replace("*",".*");if(s.isMatch(a,p)!=a.matches(r))throw new AssertionError(a+" "+p);}if(!s.isMatch("a".repeat(2000),"*".repeat(2000)))throw new AssertionError();System.out.println("Samples and original edge/reference checks passed");}}